import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import sr from '@utils/sr';
import { srConfig } from '@config';
import { StyledContainer, StyledTitle, StyledGrid, StyledMoreButton } from '../styles/certifications-styles';
import CertificationGrid from '../subsections/CertificationGrid';

const Certifications = ({ data }) => {
  const [showMore, setShowMore] = useState(false);
  const revealTitle = useRef(null);
  const revealProjects = useRef([]);

  useEffect(() => {
    sr.reveal(revealTitle.current, srConfig());
    revealProjects.current.forEach((ref, i) => sr.reveal(ref, srConfig(i * 100)));
  }, []);

  const GRID_LIMIT = 9;
  const projects = data.filter(({ node }) => node);
  const firstSix = projects.slice(0, GRID_LIMIT);
  const projectsToShow = showMore ? projects : firstSix;

  return (
    <StyledContainer id="certifications">
      <StyledTitle ref={revealTitle}>Certifications</StyledTitle>
      <StyledGrid>
        <CertificationGrid projects={projectsToShow} revealProjects={revealProjects} gridLimit={GRID_LIMIT} />
      </StyledGrid>
      {projects.length > GRID_LIMIT && (
        <StyledMoreButton onClick={() => setShowMore(!showMore)}>
          Show {showMore ? 'Less' : 'More'}
        </StyledMoreButton>
      )}
    </StyledContainer>
  );
};

Certifications.propTypes = {
  data: PropTypes.array.isRequired,
};

export default Certifications;