import { useState, useMemo, useCallback } from 'react';

/**
 * Hook for advanced project filtering with multi-tag selection
 * @param {Array} projects - Array of project nodes from GraphQL
 * @param {Array} projectOrder - Array of project titles defining sort order
 * @returns {Object} Filter state and controls
 */
const useProjectFilter = (projects, projectOrder = []) => {
  const [selectedTags, setSelectedTags] = useState([]);
  const [filterMode, setFilterMode] = useState('OR'); // 'AND' | 'OR'

  // Extract all unique tags from projects
  const allTags = useMemo(() => {
    const tagSet = new Set();
    projects.forEach(({ node }) => {
      const { tags } = node.frontmatter;
      tags?.forEach(tag => tagSet.add(tag));
    });
    return Array.from(tagSet).sort();
  }, [projects]);

  // Count projects per tag
  const tagCounts = useMemo(() => {
    const counts = {};
    allTags.forEach(tag => {
      counts[tag] = projects.filter(({ node }) =>
        node.frontmatter.tags?.includes(tag)
      ).length;
    });
    return counts;
  }, [projects, allTags]);

  // Filter projects based on selected tags and mode
  const filteredProjects = useMemo(() => {
    // If no tags selected, show all projects
    if (selectedTags.length === 0) {
      return [...projects].sort((a, b) => {
        const aIndex = projectOrder.indexOf(a.node.frontmatter.title);
        const bIndex = projectOrder.indexOf(b.node.frontmatter.title);
        return aIndex - bIndex;
      });
    }

    const filtered = projects.filter(({ node }) => {
      const projectTags = node.frontmatter.tags || [];

      if (filterMode === 'AND') {
        // Project must have ALL selected tags
        return selectedTags.every(tag => projectTags.includes(tag));
      } else {
        // Project must have ANY of the selected tags
        return selectedTags.some(tag => projectTags.includes(tag));
      }
    });

    // Sort by project order
    return filtered.sort((a, b) => {
      const aIndex = projectOrder.indexOf(a.node.frontmatter.title);
      const bIndex = projectOrder.indexOf(b.node.frontmatter.title);
      return aIndex - bIndex;
    });
  }, [projects, selectedTags, filterMode, projectOrder]);

  // Toggle a tag in/out of selection
  const toggleTag = useCallback((tag) => {
    setSelectedTags(prev => {
      if (prev.includes(tag)) {
        return prev.filter(t => t !== tag);
      }
      return [...prev, tag];
    });
  }, []);

  // Select a single tag (replaces current selection)
  const selectTag = useCallback((tag) => {
    setSelectedTags([tag]);
  }, []);

  // Clear all selected tags
  const clearFilters = useCallback(() => {
    setSelectedTags([]);
  }, []);

  // Toggle filter mode between AND/OR
  const toggleFilterMode = useCallback(() => {
    setFilterMode(prev => prev === 'AND' ? 'OR' : 'AND');
  }, []);

  return {
    // State
    selectedTags,
    filterMode,
    allTags,
    tagCounts,
    filteredProjects,

    // Actions
    toggleTag,
    selectTag,
    clearFilters,
    setFilterMode,
    toggleFilterMode,

    // Computed
    hasActiveFilters: selectedTags.length > 0,
    totalProjects: projects.length,
    filteredCount: filteredProjects.length,
  };
};

export default useProjectFilter;
