import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import { email } from '@config';
import { theme } from '@styles';
import { usePrefersReducedMotion } from '@hooks';
import { StyledContainer } from '../styles/hero-styles';
import HeroTitle from '../subsections/HeroTitle';
import HeroAuthor from '../subsections/HeroAuthor';
import HeroSubtitle from '../subsections/HeroSubtitle';
import HeroDescription from '../subsections/HeroDescription';
import HeroButton from '../subsections/HeroButton';

const { navDelay, loaderDelay } = theme;


const Hero = ({ data }) => {
  const [isMounted, setIsMounted] = useState(false);
  const [parallaxOffset, setParallaxOffset] = useState(0);
  const containerRef = useRef(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  // const location = useLocation();
  // const currentProfile = location.pathname.replaceAll('/', '') || defaultProfile;

  useEffect(() => {
    const timeout = setTimeout(() => setIsMounted(true), navDelay);
    return () => clearTimeout(timeout);
  }, []);

  // Parallax scroll effect
  useEffect(() => {
    if (prefersReducedMotion) return;

    const handleScroll = () => {
      const scrollY = window.scrollY;
      // Apply parallax effect (move slower than scroll)
      setParallaxOffset(scrollY * 0.3);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [prefersReducedMotion]);

  const { frontmatter, html } = data[0].node;

  const items = [
    <HeroTitle title={frontmatter.title} delay="100ms" />,
    <HeroAuthor name={frontmatter.name} delay="200ms" />,
    <HeroSubtitle subtitle={frontmatter.subtitle} delay="300ms" />,
    <HeroDescription html={html} delay="400ms" />,
    <HeroButton buttonText={frontmatter.buttonText} delay="500ms" email={email} />,
  ];

  const parallaxStyle = prefersReducedMotion
    ? {}
    : { transform: `translateY(${parallaxOffset}px)` };

  return (
    <StyledContainer ref={containerRef} style={parallaxStyle}>
      <TransitionGroup component={null}>
        {isMounted &&
          items.map((item, i) => (
            <CSSTransition key={i} classNames="fadeup" timeout={loaderDelay}>
              {item}
            </CSSTransition>
          ))}
      </TransitionGroup>
    </StyledContainer>
  );


  // Feature: Below is the logic for add other profile access buttons
  // const otherProfiles = []
  // for (const [key, value] of Object.entries(profileToOtherProfileLinks)) {
  //   if (key !== currentProfile) {
  //     otherProfiles.push(<StyledProfileLinks href={`${value['link']}`}>{value['message']}</StyledProfileLinks>);
  //   }
  // }

  // const six = () => (
  //   otherProfiles.map((profile, i) => (
  //     <div style={{ transitionDelay: '500ms' }}>
  //       <StyledEmailLink2 href={`${profile['link']}`}>{profile['message']}</StyledEmailLink2>
  //     </div>
  //   ))
  // );

  // const six2 = () => (
  //   <div style={{ transitionDelay: '500ms' }}>
  //     {otherProfiles}
  //   </div>
  // );
};

Hero.propTypes = {
  data: PropTypes.array.isRequired,
};

export default Hero;
