import React, { useRef } from 'react';
import PropTypes from 'prop-types';
import { TransitionGroup, CSSTransition } from 'react-transition-group';
import { FormattedIcon } from '@components/icons';
import Carousel from 'react-bootstrap/Carousel';
import { useTilt, usePrefersReducedMotion } from '@hooks';
import {
    StyledProject,
    StyledContent,
    StyledLabel,
    StyledProjectName,
    StyledDescription,
    StyledTechList,
    StyledLinkWrapper,
    StyledImgContainer,
    StyledFeaturedImg,
    StyledProjectGrid,
} from '../styles/featured-style';

// Wrapper component to apply tilt effect to each project
const TiltableProject = ({ children, revealRef, className, prefersReducedMotion, nodeRef }) => {
    const tiltRef = useRef(null);
    useTilt(tiltRef, { maxTilt: 10, scale: 1.02, disabled: prefersReducedMotion });

    return (
        <StyledProject
            ref={(el) => {
                tiltRef.current = el;
                if (nodeRef) nodeRef.current = el;
                if (revealRef) revealRef(el);
            }}
            className={className}
        >
            {children}
        </StyledProject>
    );
};

const ProjectList = ({ projects, revealProjects }) => {
    const prefersReducedMotion = usePrefersReducedMotion();

    // Create refs for each project for CSSTransition
    const nodeRefs = useRef({});

    const getNodeRef = (key) => {
        if (!nodeRefs.current[key]) {
            nodeRefs.current[key] = React.createRef();
        }
        return nodeRefs.current[key];
    };

    return (
        <StyledProjectGrid>
            <TransitionGroup component={null}>
                {projects &&
                    projects.map(({ node }, i) => {
                        const { frontmatter, html } = node;
                        const { external, title, tech, github, imageCarousel, gifCarousel, drive, youtube } = frontmatter;

                        const hasImages = (imageCarousel && imageCarousel.length > 0) || (gifCarousel && gifCarousel.length > 0);
                        const projectKey = title || `project-${i}`;
                        const nodeRef = getNodeRef(projectKey);

                        return (
                            <CSSTransition
                                key={projectKey}
                                nodeRef={nodeRef}
                                timeout={{ enter: 300, exit: 200 }}
                                classNames="project"
                            >
                                <TiltableProject
                                    className={!hasImages ? 'no-image' : ''}
                                    revealRef={el => (revealProjects.current[i] = el)}
                                    prefersReducedMotion={prefersReducedMotion}
                                    nodeRef={nodeRef}
                                >
                                    <StyledContent>
                                        <StyledLabel>Featured Project</StyledLabel>
                                        <StyledProjectName>
                                            {external ? (
                                                <a href={external} target="_blank" rel="nofollow noopener noreferrer">
                                                    {title}
                                                </a>
                                            ) : (
                                                title
                                            )}
                                        </StyledProjectName>
                                        <StyledDescription dangerouslySetInnerHTML={{ __html: html }} />
                                        {tech && (
                                            <StyledTechList>
                                                {tech.map((item, i) => (
                                                    <li key={i}>{item}</li>
                                                ))}
                                            </StyledTechList>
                                        )}
                                        <StyledLinkWrapper>
                                            {github && (
                                                <a href={github} target="_blank" rel="nofollow noopener noreferrer">
                                                    <FormattedIcon name="GitHub" />
                                                </a>
                                            )}
                                            {drive && (
                                                <a href={drive} target="_blank" rel="nofollow noopener noreferrer">
                                                    <FormattedIcon name="Drive" />
                                                </a>
                                            )}
                                            {external && (
                                                <a href={external} target="_blank" rel="nofollow noopener noreferrer">
                                                    <FormattedIcon name="External" />
                                                </a>
                                            )}
                                            {youtube && (
                                                <a href={youtube} target="_blank" rel="nofollow noopener noreferrer">
                                                    <FormattedIcon name="Youtube" />
                                                </a>
                                            )}
                                        </StyledLinkWrapper>
                                    </StyledContent>

                                    <StyledImgContainer>
                                        <Carousel
                                            interval={5000}
                                            pause="hover"
                                            touch={true}
                                            slide={true}
                                        >
                                            {imageCarousel && imageCarousel.map((image, idx) => (
                                                image && image.childImageSharp ? (
                                                    <Carousel.Item key={idx}>
                                                        <StyledFeaturedImg image={image.childImageSharp.gatsbyImageData} alt={`Cover ${idx + 1}`} />
                                                    </Carousel.Item>
                                                ) : null
                                            ))}

                                            {gifCarousel && gifCarousel.map((gif, idx) => (
                                                gif ? (
                                                    <Carousel.Item key={`gif-${idx}`}>
                                                        <img src={gif} alt="img" />
                                                    </Carousel.Item>
                                                ) : null
                                            ))}

                                        </Carousel>
                                    </StyledImgContainer>
                                </TiltableProject>
                            </CSSTransition>
                        );
                    })}
            </TransitionGroup>
        </StyledProjectGrid>
    );
};

ProjectList.propTypes = {
    projects: PropTypes.array.isRequired,
    revealProjects: PropTypes.object.isRequired,
};

export default ProjectList;
