import React from 'react';
import PropTypes from 'prop-types';
import { StyledOverline } from '../styles/hero-styles';

const HeroTitle = ({ title, delay }) => (
    <StyledOverline style={{ transitionDelay: delay }}>{title}</StyledOverline>
);

HeroTitle.propTypes = {
    title: PropTypes.string.isRequired,
    delay: PropTypes.string.isRequired,
};

export default HeroTitle;