export const StyledFeaturedImg = styled(GatsbyImage)`
  width: 100%;
  max-width: 100%;
  vertical-align: middle;
  border-radius: ${theme.borderRadius};
  position: relative;
  
  
  ${media.tablet`
    object-fit: cover;
    width: auto;
    height: 100%;
  `};
`;

export const StyledImgContainer = styled.div`
  ${mixins.boxShadow};
  grid-column: 7 / -1;
  grid-row: 1 / -1;
  position: relative;
  z-index: 1;
  border-radius: ${theme.radius + 1}px;
  transition: ${theme.transition};
  overflow: hidden;

  ${media.tablet`height: 100%;`};

  ${media.thone`
    grid-column: 1 / -1;
  `};

  /* Image zoom effect on hover */
  .gatsby-image-wrapper,
  img {
    transition: transform 500ms ${theme.easing};
  }

  &:hover {
    .gatsby-image-wrapper,
    img {
      transform: scale(1.05);
    }
  }

  /* Enhanced carousel transitions */
  .carousel-item {
    transition: transform 500ms ${theme.easing}, opacity 500ms ${theme.easing};
  }

  .carousel-control-prev,
  .carousel-control-next {
    opacity: 0;
    transition: opacity 300ms ${theme.easing};
  }

  &:hover {
    .carousel-control-prev,
    .carousel-control-next {
      opacity: 0.8;
    }
  }

  .carousel-indicators {
    margin-bottom: 0.5rem;

    button {
      background-color: var(--color-accent);
      opacity: 0.5;
      transition: opacity 300ms ${theme.easing};

      &.active {
        opacity: 1;
      }
    }
  }
`;

export const StyledProject = styled.div`
  display: grid;
  grid-gap: 10px;
  grid-template-columns: repeat(12, 1fr);
  align-items: center;
  margin-bottom: 100px;

  ${media.thone`
    margin-bottom: 70px;
  `};

  &:last-of-type {
    margin-bottom: 0;
  }

  &:nth-of-type(odd) {
    ${StyledContent} {
      grid-column: 7 / -1;
      text-align: justify;
      
      ${media.thone`
        grid-column: 1 / -1;
        padding: 40px 40px 30px;
      `};
      
      ${media.phablet`padding: 30px 25px 20px;`};
    }

    ${StyledTechList} {
      justify-content: flex-end;
      li {
        margin-left: ${theme.margin};
        margin-right: 0;
      }
    }
    
    ${StyledLinkWrapper} {
      justify-content: flex-end;
      margin-left: 0;
      margin-right: -10px;
    }

    ${StyledImgContainer} {
      grid-column: 1 / 7;
      
      ${media.tablet`height: 100%;`};
      
      ${media.thone`
        grid-column: 1 / -1;
      `};
    }
  }

  &.no-image ${StyledContent} {
    grid-column: 2 / -3; /* Make StyledContent occupy all columns */
  }

  &.no-image ${StyledImgContainer} {
    display: none; /* Hide the image container if no images are available */
  }
`;

