// Project grid animation styles
export const StyledProjectGrid = styled.div`
  position: relative;

  .project-enter {
    opacity: 0;
    transform: scale(0.95) translateY(20px);
  }

  .project-enter-active {
    opacity: 1;
    transform: scale(1) translateY(0);
    transition: opacity 300ms ${theme.easing}, transform 300ms ${theme.easing};
  }

  .project-exit {
    opacity: 1;
    transform: scale(1);
  }

  .project-exit-active {
    opacity: 0;
    transform: scale(0.95);
    transition: opacity 200ms ${theme.easing}, transform 200ms ${theme.easing};
  }
`;